const b = $input.first().json.body || {};
return [{
  json: {
    accion: String(b.accion || '').trim().toLowerCase(),
    token: String(b.token || '').trim(),
    nombre: String(b.nombre || '').trim().replace(/\s+/g, ' '),
    email: String(b.email || '').trim().toLowerCase(),
    password: String(b.password || ''),
    password_actual: String(b.password_actual || ''),
    password_nueva: String(b.password_nueva || ''),
    codigo: String(b.codigo || '').replace(/\D/g, '').slice(0, 6),
  },
}];

const d = $input.first().json;
const errores = [];
if (d.nombre.length < 3 || d.nombre.length > 60) errores.push('el nombre debe tener entre 3 y 60 caracteres');
if (d.email.length > 120 || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(d.email)) errores.push('el correo no es válido');
if (d.password.length < 8) errores.push('la contraseña debe tener mínimo 8 caracteres');
if (errores.length) {
  const msg = errores.join(', ');
  return [{ json: { ...d, valido: false, error_status: 400, error_codigo: 'DATOS_INVALIDOS', error_mensaje: msg.charAt(0).toUpperCase() + msg.slice(1) + '.' } }];
}
return [{ json: { ...d, valido: true } }];

const crypto = require('crypto');
const d = $('Validar datos (código)').first().json;
const no = (s, c, m) => [{ json: { ok: false, error_status: s, error_codigo: c, error_mensaje: m } }];
if ($('Leer usuarios (código)').all().some(i => i.json.email_normalizado === d.email)) {
  return no(409, 'EMAIL_DUPLICADO', 'Ya existe una cuenta con ese correo.');
}
const ahoraMs = Date.now();
const horaCO = (ms) => new Date(ms - 5 * 3600 * 1000).toISOString().slice(0, 19) + '-05:00';
const pendientes = $('Leer verificaciones').all().map(i => i.json)
  .filter(v => v.email_normalizado === d.email && v.estado === 'PENDIENTE');
// para que no se puedan pedir codigos sin parar: uno por minuto
const ultimo = pendientes.map(v => new Date(v.creado_en).getTime()).sort((a, b) => b - a)[0];
if (ultimo && ahoraMs - ultimo < 60 * 1000) {
  return no(429, 'ESPERA_UN_MINUTO', 'Ya te enviamos un código hace un momento. Espera un minuto para pedir otro.');
}
const codigo = String(crypto.randomInt(0, 1000000)).padStart(6, '0');
// en la hoja no queda el codigo, solo su hash
const hash = crypto.createHash('sha256').update(d.email + ':' + codigo).digest('hex');
return [{
  json: {
    ok: true,
    verificacion_id: 'VER-' + ahoraMs.toString(36).toUpperCase(),
    email_normalizado: d.email,
    codigo_hash: hash,
    creado_en: horaCO(ahoraMs),
    expira_en: horaCO(ahoraMs + 10 * 60 * 1000),
    estado: 'PENDIENTE',
    intentos: 0,
    usado_en: '',
    _codigo: codigo,
    _nombre: d.nombre,
    _cancelar: pendientes.map(v => v.verificacion_id),
  },
}];

const v = $('Generar código de verificación').first().json;
    const nombre = v._nombre.split(' ')[0];
    const html = `
<div style="font-family:Arial,Helvetica,sans-serif;max-width:540px;margin:0 auto;border-radius:14px;overflow:hidden;border:1px solid #e7dfd1">
  <div style="background:#14213d;color:#fff4d6;padding:16px 22px;font-size:20px;font-weight:bold;border-bottom:4px solid #b3262e">EventPass <span style="color:#e8b04b">Barrio</span></div>
  <div style="padding:22px;background:#fbf7ef;color:#1d1a17;line-height:1.5">
    <p>Hola ${nombre},</p>
    <p>Este es tu código para terminar de crear la cuenta:</p>
    <p style="font-size:32px;font-weight:bold;letter-spacing:8px;color:#b3262e;text-align:center;margin:18px 0">${v._codigo}</p>
    <p>Vence en 10 minutos. Si no fuiste tú, ignora este correo.</p>
  </div>
</div>`.trim();
    return [{ json: { email: v.email_normalizado, titulo: `Tu código de EventPass Barrio: ${v._codigo}`, html } }];

const d = $input.first().json;
const errores = [];
if (d.nombre.length < 3 || d.nombre.length > 60) errores.push('el nombre debe tener entre 3 y 60 caracteres');
if (d.email.length > 120 || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(d.email)) errores.push('el correo no es válido');
if (d.password.length < 8) errores.push('la contraseña debe tener mínimo 8 caracteres');
if (errores.length) {
  const msg = errores.join(', ');
  return [{ json: { ...d, valido: false, error_status: 400, error_codigo: 'DATOS_INVALIDOS', error_mensaje: msg.charAt(0).toUpperCase() + msg.slice(1) + '.' } }];
}
return [{ json: { ...d, valido: true } }];

const d = $('Validar datos registro').first().json;
const existe = $('Leer usuarios (crear)').all().some(i => i.json.email_normalizado === d.email);
if (existe) {
  return [{ json: { ...d, duplicado: true, error_status: 409, error_codigo: 'EMAIL_DUPLICADO', error_mensaje: 'Ya existe una cuenta con ese correo.' } }];
}
return [{ json: { ...d, duplicado: false } }];

const crypto = require('crypto');
const d = $('Validar datos registro').first().json;
const ahoraMs = Date.now();
const ahora = new Date(ahoraMs - 5 * 3600 * 1000).toISOString().slice(0, 19) + '-05:00';
const no = (s, c, m, extra = {}) => [{ json: { ok: false, error_status: s, error_codigo: c, error_mensaje: m, ...extra } }];

if (!/^\d{6}$/.test(d.codigo)) return no(400, 'CODIGO_REQUERIDO', 'Escribe el código de 6 dígitos que te llegó al correo.');
const v = $('Leer verificaciones (crear)').all().map(i => i.json)
  .filter(x => x.email_normalizado === d.email && x.estado === 'PENDIENTE')
  .sort((a, b) => String(b.creado_en).localeCompare(String(a.creado_en)))[0];
if (!v) return no(400, 'CODIGO_INVALIDO', 'No hay un código activo para este correo. Pide uno nuevo.');

const intentos = Number(v.intentos || 0);
if (new Date(v.expira_en).getTime() < ahoraMs) {
  return no(400, 'CODIGO_VENCIDO', 'El código ya venció. Pide uno nuevo.', { actualizar: true, verificacion_id: v.verificacion_id, estado: 'EXPIRADO' });
}
if (intentos >= 5) {
  return no(429, 'DEMASIADOS_INTENTOS', 'Fallaste el código muchas veces. Pide uno nuevo.', { actualizar: true, verificacion_id: v.verificacion_id, estado: 'CANCELADO' });
}
const hash = crypto.createHash('sha256').update(d.email + ':' + d.codigo).digest('hex');
if (hash !== v.codigo_hash) {
  const quedan = 4 - intentos;
  return no(400, 'CODIGO_INCORRECTO', `El código no coincide. Te quedan ${quedan} intento${quedan === 1 ? '' : 's'}.`, { actualizar: true, verificacion_id: v.verificacion_id, intentos: intentos + 1 });
}
return [{ json: { ok: true, actualizar: true, verificacion_id: v.verificacion_id, estado: 'USADO', usado_en: ahora, intentos: intentos + 1 } }];

const crypto = require('crypto');
const d = $('Validar datos registro').first().json;
// sal aleatoria por usuario + pbkdf2 (100k iteraciones, sha256). Nunca se guarda la clave
const salt = crypto.randomBytes(16).toString('hex');
const hash = crypto.pbkdf2Sync(d.password, salt, 100000, 32, 'sha256').toString('hex');
const ahora = new Date(Date.now() - 5 * 3600 * 1000).toISOString().slice(0, 19) + '-05:00';
return [{
  json: {
    usuario_id: 'USR-' + Date.now().toString(36).toUpperCase() + crypto.randomBytes(2).toString('hex').toUpperCase(),
    nombre: d.nombre,
    email_normalizado: d.email,
    password_hash: hash,
    password_salt: salt,
    estado: 'ACTIVO',
    fecha_registro: ahora,
    fecha_actualizacion: ahora,
  },
}];

const u = $('Generar hash y salt').first().json;
return [{
  json: {
    auditoria_id: 'AUD-' + Date.now().toString(36).toUpperCase(),
    usuario_id: u.usuario_id,
    accion: 'CREAR',
    fecha: u.fecha_registro,
    resultado: 'OK',
    detalle: 'Registro desde la web',
  },
}];

const u = $('Generar hash y salt').first().json;
return [{
  json: {
    usuario_id: u.usuario_id,
    tipo: 'CUENTA_CREADA',
    titulo: '¡Bienvenido a EventPass Barrio!',
    mensaje: `Tu cuenta quedó creada y verificada con el correo ${u.email_normalizado}. Ya puedes ingresar, vincular tu Telegram desde tu perfil y apartar cupo en las novenas, la noche de velitas y todos los planes de diciembre.`,
  },
}];

const r = $input.first().json;
const mensajes = {
  NO_EXISTE: 'Necesitas iniciar sesión.',
  CERRADA: 'Tu sesión fue cerrada. Vuelve a ingresar.',
  EXPIRADA: 'Tu sesión expiró. Vuelve a ingresar.',
  USUARIO_INACTIVO: 'Tu cuenta está desactivada.',
};
return [{
  json: {
    status: 401,
    body: { ok: false, error: 'SESION_' + (r.motivo || 'INVALIDA'), mensaje: mensajes[r.motivo] || 'Sesión no válida.' },
  },
}];

const id = $('Validar sesión (WF02)').first().json.usuario.usuario_id;
const u = $('Leer usuarios (perfil)').all().map(i => i.json).find(x => x.usuario_id === id);
if (!u) return [{ json: { status: 404, body: { ok: false, error: 'NO_ENCONTRADO', mensaje: 'No encontramos tu usuario.' } } }];
return [{
  json: {
    status: 200,
    body: { ok: true, usuario: { usuario_id: u.usuario_id, nombre: u.nombre, email: u.email_normalizado, estado: u.estado, fecha_registro: u.fecha_registro } },
  },
}];

const crypto = require('crypto');
const d = $('Normalizar solicitud').first().json;
const id = $('Validar sesión (WF02)').first().json.usuario.usuario_id;
const u = $('Leer usuarios (actualizar)').all().map(i => i.json).find(x => x.usuario_id === id);
const error = (status, codigo, mensaje) => [{ json: { ok: false, error_status: status, error_codigo: codigo, error_mensaje: mensaje } }];

if (!u) return error(404, 'NO_ENCONTRADO', 'No encontramos tu usuario.');
const nombre = d.nombre || u.nombre;
if (nombre.length < 3 || nombre.length > 60) return error(400, 'DATOS_INVALIDOS', 'El nombre debe tener entre 3 y 60 caracteres.');

const ahora = new Date(Date.now() - 5 * 3600 * 1000).toISOString().slice(0, 19) + '-05:00';
const cambios = { usuario_id: id, nombre, fecha_actualizacion: ahora };
const detalle = [];
if (nombre !== u.nombre) detalle.push('nombre');

if (d.password_nueva) {
  if (d.password_nueva.length < 8) return error(400, 'DATOS_INVALIDOS', 'La nueva contraseña debe tener mínimo 8 caracteres.');
  const actual = crypto.pbkdf2Sync(d.password_actual, String(u.password_salt), 100000, 32, 'sha256').toString('hex');
  if (actual !== String(u.password_hash)) return error(401, 'PASSWORD_INCORRECTO', 'La contraseña actual no es correcta.');
  const salt = crypto.randomBytes(16).toString('hex');
  cambios.password_salt = salt;
  cambios.password_hash = crypto.pbkdf2Sync(d.password_nueva, salt, 100000, 32, 'sha256').toString('hex');
  detalle.push('contraseña');
}
return [{ json: { ok: true, ...cambios, _detalle: detalle.join(', ') || 'sin cambios', _email: u.email_normalizado } }];

const crypto = require('crypto');
const d = $('Normalizar solicitud').first().json;
const id = $('Validar sesión (WF02)').first().json.usuario.usuario_id;
const u = $('Leer usuarios (desactivar)').all().map(i => i.json).find(x => x.usuario_id === id);
if (!u) return [{ json: { ok: false, error_status: 404, error_codigo: 'NO_ENCONTRADO', error_mensaje: 'No encontramos tu usuario.' } }];
const hash = crypto.pbkdf2Sync(d.password, String(u.password_salt), 100000, 32, 'sha256').toString('hex');
if (hash !== String(u.password_hash)) {
  return [{ json: { ok: false, error_status: 401, error_codigo: 'PASSWORD_INCORRECTO', error_mensaje: 'La contraseña no es correcta.' } }];
}
const ahora = new Date(Date.now() - 5 * 3600 * 1000).toISOString().slice(0, 19) + '-05:00';
return [{ json: { ok: true, usuario_id: id, estado: 'INACTIVO', fecha_actualizacion: ahora } }];

const d = $input.first().json;
return [{
  json: {
    status: d.error_status || 400,
    body: { ok: false, error: d.error_codigo || 'ERROR', mensaje: d.error_mensaje || 'No se pudo procesar la solicitud.' },
  },
}];
